1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export type StepResult =
41	  | { premium: number }
42	  | { payout: number; remainingCap: number };
43	
44	export interface ScenarioResult {
45	  results: StepResult[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	
50	const BASE_PREMIUMS = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	} as const satisfies Record<string, number>;
58	
59	type InsurableItemType = keyof typeof BASE_PREMIUMS;
60	
61	const isInsurable = (type: string): type is InsurableItemType =>
62	  type in BASE_PREMIUMS;
63	
64	const basePremiumOf = (item: Item): number => {
65	  if (!isInsurable(item.type)) {
66	    throw new Error(`The MHPCO does not insure a ${item.type}`);
67	  }
68	  return BASE_PREMIUMS[item.type];
69	};
70	
71	/** Premiums are rounded up — in MHPCO's favour. */
72	const roundPremium = (amount: number): number => Math.ceil(amount);
73	
74	const COMPONENT_BLOCK_SIZE = 3;
75	const COMPONENT_BLOCK_PREMIUM = 60;
76	
77	/** Items of a single type, kept together so the block rule can be applied. */
78	type SameTypeGroup = Item[];
79	
80	const groupByType = (items: Item[]): SameTypeGroup[] => {
81	  const groups = new Map<string, SameTypeGroup>();
82	  for (const item of items) {
83	    const group = groups.get(item.type) ?? [];
84	    group.push(item);
85	    groups.set(item.type, group);
86	  }
87	  return [...groups.values()];
88	};
89	
90	const sumBasePremiums = (group: SameTypeGroup): number =>
91	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
92	
93	/**
94	 * Exactly three alike items form a building block priced at a flat premium;
95	 * any other count is priced per item.
96	 */
97	const blockAwareBasePremium = (group: SameTypeGroup): number =>
98	  group.length === COMPONENT_BLOCK_SIZE
99	    ? COMPONENT_BLOCK_PREMIUM
100	    : sumBasePremiums(group);
101	
102	const policyBasePremiumFor = (items: Item[]): number =>
103	  groupByType(items).reduce(
104	    (sum, group) => sum + blockAwareBasePremium(group),
105	    0,
106	  );
107	
108	const HIGH_ENCHANTMENT_LEVEL = 5;
109	
110	const isCursed = (item: Item): boolean => item.cursed === true;
111	const isHighlyEnchanted = (item: Item): boolean =>
112	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
113	
114	/**
115	 * An item-specific surcharge: when the item triggers the clause, it is charged
116	 * a rate of that item's own base premium — never of the whole policy's.
117	 */
118	interface ItemSurcharge {
119	  appliesTo: (item: Item) => boolean;
120	  rate: number;
121	}
122	
123	const ITEM_SURCHARGES: ItemSurcharge[] = [
124	  { appliesTo: isCursed, rate: 0.5 },
125	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
126	];
127	
128	/** Every clause the item triggers stacks, each on that item's base premium. */
129	const surchargeRateFor = (item: Item): number =>
130	  ITEM_SURCHARGES.reduce(
131	    (rate, surcharge) =>
132	      surcharge.appliesTo(item) ? rate + surcharge.rate : rate,
133	    0,
134	  );
135	
136	const itemSurchargesFor = (items: Item[]): number =>
137	  items.reduce(
138	    (sum, item) => sum + basePremiumOf(item) * surchargeRateFor(item),
139	    0,
140	  );
141	
142	/** Every quote is an initial assessment, so this surcharge always applies. */
143	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
144	const LOYALTY_DISCOUNT_RATE = -0.2;
145	const LOYALTY_YEARS = 2;
146	
147	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
148	
149	/** What the MHPCO knows about the customer when pricing a particular quote. */
150	interface QuoteContext {
151	  customer: Customer;
152	  previousContracts: number;
153	}
154	
155	const isLoyal = ({ customer }: QuoteContext): boolean =>
156	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
157	const isFollowUpContract = ({ previousContracts }: QuoteContext): boolean =>
158	  previousContracts > 0;
159	
160	/**
161	 * A policy-wide modifier: when the customer triggers the clause, the whole
162	 * policy's base premium is adjusted by that rate — never a single item's.
163	 * A negative rate is a discount.
164	 */
165	interface PolicyModifier {
166	  appliesTo: (context: QuoteContext) => boolean;
167	  rate: number;
168	}
169	
170	/** Conditional clauses, on top of the surcharge every quote already carries. */
171	const POLICY_MODIFIERS: PolicyModifier[] = [
172	  { appliesTo: isLoyal, rate: LOYALTY_DISCOUNT_RATE },
173	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_DISCOUNT_RATE },
174	];
175	
176	/** Every clause the customer triggers stacks on the policy base premium. */
177	const policyModifierRateFor = (context: QuoteContext): number =>
178	  POLICY_MODIFIERS.reduce(
179	    (rate, modifier) =>
180	      modifier.appliesTo(context) ? rate + modifier.rate : rate,
181	    FIRST_INSURANCE_SURCHARGE_RATE,
182	  );
183	
184	const quotePremium = (items: Item[], context: QuoteContext): number => {
185	  const policyBasePremium = policyBasePremiumFor(items);
186	  return roundPremium(
187	    policyBasePremium +
188	      policyBasePremium * policyModifierRateFor(context) +
189	      itemSurchargesFor(items) +
190	      PROCESSING_FEE,
191	  );
192	};
193	
194	const INSURANCE_VALUES = {
195	  sword: 1000,
196	  amulet: 600,
197	  staff: 800,
198	  potion: 400,
199	  rune: 250,
200	  moonstone: 250,
201	} as const satisfies Record<InsurableItemType, number>;
202	
203	const insuranceValueOf = (item: Item): number =>
204	  INSURANCE_VALUES[item.type as InsurableItemType];
205	
206	const DEDUCTIBLE = 100;
207	const CAP_MULTIPLIER = 2;
208	
209	/** Payouts are rounded down — in MHPCO's favour. */
210	const roundPayout = (amount: number): number => Math.floor(amount);
211	
212	/** A policy created by a quote step, tracked so later claims can draw on it. */
213	interface Policy {
214	  items: Item[];
215	  remainingCap: number;
216	}
217	
218	const openPolicy = (items: Item[]): Policy => ({
219	  items,
220	  remainingCap:
221	    CAP_MULTIPLIER * items.reduce((sum, item) => sum + insuranceValueOf(item), 0),
222	});
223	
224	const FULL_REIMBURSEMENT_RATE = 1;
225	
226	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
227	const REDUCED_REIMBURSEMENT_RATE = 0.5;
228	
229	/** Damage to a very highly enchanted item is only half reimbursed. */
230	const reimbursementRateFor = (item: Item): number =>
231	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL
232	    ? REDUCED_REIMBURSEMENT_RATE
233	    : FULL_REIMBURSEMENT_RATE;
234	
235	/** The deductible can absorb a small damage entirely, but never turns it into a debt. */
236	const afterDeductible = (amount: number): number =>
237	  Math.max(0, amount - DEDUCTIBLE);
238	
239	const payoutForDamage = (damage: Damage, item: Item): number =>
240	  afterDeductible(damage.amount * reimbursementRateFor(item));
241	
242	/**
243	 * Settling draws the payout from the policy's cap, so it yields the policy as
244	 * it stands afterwards rather than modifying the one passed in — the caller
245	 * decides whether to keep the drawn-down policy.
246	 */
247	interface Settlement {
248	  result: StepResult;
249	  policy: Policy;
250	}
251	
252	/** A damage entry together with the insured item it will be settled against. */
253	interface ClaimedDamage {
254	  damage: Damage;
255	  item: Item;
256	}
257	
258	/**
259	 * Each damage entry is settled against a distinct insured item, so claiming
260	 * for more items of a type than the policy covers is rejected outright — as is
261	 * a damage that could never have happened. Both are checked before any money is
262	 * computed, so an unsettleable claim is rejected whole rather than in part.
263	 */
264	const matchDamagesToInsuredItems = (
265	  policy: Policy,
266	  damages: Damage[],
267	): ClaimedDamage[] => {
268	  const unclaimed = [...policy.items];
269	  return damages.map((damage) => {
270	    if (damage.amount < 0) {
271	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
272	    }
273	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
274	    if (index === -1) {
275	      throw new Error(`${damage.itemType} is not insured by this policy`);
276	    }
277	    return { damage, item: unclaimed.splice(index, 1)[0] };
278	  });
279	};
280	
281	const settleClaim = (policy: Policy, incident: Incident): Settlement => {
282	  const claimedPayout = matchDamagesToInsuredItems(
283	    policy,
284	    incident.damages,
285	  ).reduce((sum, { damage, item }) => sum + payoutForDamage(damage, item), 0);
286	  const payout = roundPayout(Math.min(claimedPayout, policy.remainingCap));
287	  const remainingCap = policy.remainingCap - payout;
288	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
289	};
290	
291	export const runScenario = (scenario: Scenario): ScenarioResult => {
292	  let previousContracts = 0;
293	  const policies = new Map<number, Policy>();
294	
295	  const results = scenario.steps.map((step, index) => {
296	    if (step.op === "quote") {
297	      const context = { customer: scenario.customer, previousContracts };
298	      previousContracts += 1;
299	      policies.set(index, openPolicy(step.items));
300	      return { premium: quotePremium(step.items, context) };
301	    }
302	
303	    const policy = policies.get(step.policy);
304	    if (policy === undefined) {
305	      throw new Error(`No policy created by step ${step.policy}`);
306	    }
307	    const settlement = settleClaim(policy, step.incident);
308	    policies.set(step.policy, settlement.policy);
309	    return settlement.result;
310	  });
311	
312	  return { results };
313	};
